INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62045069', 62045069, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Manajer Operasional dan Respon Respon Opini Publik Januari - Oktober 1 #1', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 167750000, 'December 2025', 'APBD', 1, 1, '1 Orang x 10 Bulan', '1. Melakukan fungsi manajerial dalam pengelolaan respon opini publik terhadap laporan pengaduan/ opini masyarakat sehingga dapat ditindaklanjuti oleh Perangkat Daerah terkait; 2. Melakukan fungsi manajerial dalam penggunaan dan pemanfaatan ruang pemantauan JSC; 3. Mengoordinasikan, mengendalikan aktivitas, dan membagi tugas tim di bawahnya; 4. Mengawasi dan melaporkan pekerjaan serta hasilnya kepada pimpinan; 5. Menyusun rencana sosialisasi dan kampanye kepada masyarakat agar dapat memanfaatkan produk layanan JSC; 6. Koordinasi terkait hal teknis dengan Perangkat Daerah terkait sehingga dapat mempercepat tindaklanjut pengaduan masyarakat, serta memberikan bantuan konsultasi aplikasi Jakarta Smart City; 7. Menganalisa dinamika alur pelaporan pengaduan/ opini dari masyarakat serta mengecek kondisi lapangan; 8. Menganalisa permasalahan dan isu pengelolaan respon opini publik; 9. Merancang skenario penggiringan opini pada sosial media pimpinan agar mendapatkan penilaian positif dari masyarakat; 10. Menyusun rencana sosialisasi sehingga masyarakat mengetahui berbagai kanal pengaduan Pemerintah Provinsi DKI Jakarta; 11. Memastikan perangkat pendukung operasional berfungsi dengan baik dan melaporkan kepada pimpinan jika terjadi kendala atau kerusakan; 12. Berpartisipasi dalam mengembangkan SOP Divisi; 13. Menilai kinerja anggota divisi.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 4 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 167750000, 'high', 'Uraian pekerjaan memuat perancangan skenario penggiringan opini pada media sosial pimpinan untuk memperoleh penilaian positif masyarakat. Aktivitas ini berindikasi penggunaan dana publik untuk pembentukan citra personal/propaganda, bukan fokus utama pelayanan publik atau penanganan pengaduan yang netral. Seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan karena tujuan tersebut tampak tidak patut dibiayai APBD.', NULL, NULL, 3, 1, 1, 1, 1, 133555);
