INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62052299', 62052299, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KEPENDUDUKAN DAN PENCATATAN SIPIL KABUPATEN ADMINISTRASI KEPULAUAN SERIBU', 'Penyediaan Jasa Surat Menyurat/Caraka', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Adm. Kepulauan Seribu (Kab.)', 146196146, 'December 2025', 'APBD', 1, 1, '2 Orang', 'Penunjang operasional kantor khususnya kegiatan pengiriman surat menyurat perkantoran, distribusi dokumen admindukcapil dan distribusi BMD di tingkat Sudin, Kecamatan, RSUD/ RSUK/ Puskesmas dan tingkat Kelurahan di Sudin Kependudukan dan Pencatatan Sipil Kabupaten Administrasi Kepulauan Seribu, dapat berjalan secara optimal dan tepat sasaran, sehingga kegiatan pelayanan adminduk kepada masyarakat dapat berjalan dengan lancar dan baik.', 'Spesifikasi Pekerjaan Kualifikasi Pekerja Kontrak yang dibutuhkan dalam kegiatan pelayanan Pendaftaran Penduduk dan Pencatatan Sipil adalah: a. Laki-laki/Perempuan; b. Batas Usia Minimal 19 tahun dan Maksimal 56 tahun; c. Pendidikan minimal SLTA/sederajat; d. Memiliki Akses transportasi untuk pendistribusian dokumen/surat dan barang antar pulau; e. Berbadan sehat, yang dibuktikan dengan surat keterangan sehat dari Puskesmas atau Rumah Sakit lainnya (setelah dinyatakan lulus); f. Berkelakukan baik, dibuktikan dengan SKCK dari Kepolisian yang masih berlaku; g. Melampirkan fotocopy KK dan KTP; h. Memiliki NPWP; i. Melampirkan CV (Curriculum vitae/Daftar Riwayat Hidup).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 135624);
