INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61988763', 61988763, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK', 'Pengadaan Tenaga Ahli Analisis #1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 130075000, 'December 2025', 'APBD', 1, 1, '1 Orang x 11 Bulan', '1) Mempelajari isu-isu strategis serta visi dan misi Pemerintah Provinsi DKI Jakarta; 2) Merancang kajian dan kampanye terkait isu-isu perkotaan; 3) Kajian dan kampanye berfokus pada tingkah laku masyarakat dan berorientasi pada perubahan tingkah laku kelompok masyarakat tersebut, dengan melakukan eksperimen dan intervensi sosial; 4) Pemantauan pelaksanaan analisis kebutuhan data dan upaya pemenuhan atas kebutuhan data; 5) Menetapkan pemetaan dan penyempurnaan pemetaan data sektoral dari masing-masing Perangkat Daerah (PD) dan Instansi sumber data; 6) Menetapkan metode pengumpulan data dan pemutakhiran data beserta metadatanya; 7) Menetapkan jadwal pelaksanaan koordinasi dengan PD dan instansi sumber data; 8) Kajian dan kampanye berfokus pada tingkah laku masyarakat dan berorientasi pada perubahan tingkah laku kelompok masyarakat tersebut, dengan melakukan eksperimen dan intervensi sosial; 9) Menjaga kualitas dari produk kajian; 10) Menetapkan rancangan pelaksanaan survei dengan pembagian struktur yang jelas; 11) Pemantauan pengelolaan dan penyimpanan data hasil survei dengan pembagian struktur yang jelas; 12) Pemantauan pelaksanaan analisis data untuk publikasi statistik; 13) Mengevaluasi pengumpulan/pemutakhiran data beserta metadatanya dari PD dan instansi sumber daya; 14) Mengevaluasi metode/prosedur pengelolaan data; 15) Melaksanakan tugas lainnya yang diperintahkan oleh Kepala Bidang Data dan Statistik dan/atau Ketua Subkelompok Statistik dan Analisis Kebijakan; 16) Membuat laporan pelaksanaan pekerjaan dalam bentuk tulisan/paper dan/atau presentasi serta softcopy.', '• Pendidikan minimal S1 Jurusan Antropologi /Antropologi Sosial /Sastra Indonesia /Ekonomi Pembangunan /Administrasi Publik /Ilmu Administrasi Publik /Pemanfaatan Sumber Daya Perikanan /Psikologi /Informatika /Fisika /Teknik Elektro /Matematika/Statistika • Memiliki pengalaman minimal 3 tahun • Memiliki sertifikasi kompetensi terkait “Data Management Staff” yang dikeluarkan oleh BNSP, atau Instansi yang berwenang berdasarkan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 137838);
