INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62051887', 62051887, 'analyze_legacy', 'Kementerian Pertahanan', 'central', 'SESKOAL TNI AL', 'PERBAIKAN BERAT RUMDIS BA/TA T-36/12 UNIT SESKOAL', 'Pekerjaan Konstruksi', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 2510212000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 GIAT', 'A PEKERJAAN PERSIAPAN B PEKERJAAN PENDAHULUAN C PEKERJAAN ATAP DAN PLAFOND D PEKERJAAN PASANGAN E PERBAIKAN KUSEN DAN PINTU F PEKERJAAN INSTALASI LISTRIK G PEKERJAAN INSTALASI AIR H PEKERJAAN PENGECATAN I PEKERJAAN LAIN-LAIN', 'A PEKERJAAN PERSIAPAN 1 Pembuatan bedeng pekerja dan Gudang Material Pembuatan bedeng pekerja dan Gudang Material 2 Mobilisasi dan Demobilisasi Mobilisasi pekerja dan alat 3 Dokumentasi Pendokumentasian selama proyek 4 Pembersihan lapangan Pembersihan lapangan setelah pelaksanaan pekerjaan sampai bersih B PEKERJAAN PENDAHULUAN 1. Bongkar genteng Pembongkaran genteng 2. Bongkar karpusan genteng Pembongkaran karpusan genteng 3. Bongkar kuda - kuda kayu Pembongkaran kuda - kuda kayu 4. Bongkar kaso + reng Pembongkaran kaso + reng 5. Bongkar rangka plafond Pembongkaran rangka plafond 6. Bongkar plafond triplek Pembongkaran plafond triplek 7. Bongkar list plafond Pembongkaran list plafond 8. Bongkar listplank Pembongkaran listplank 9. Bongkar keramik lantai Pembongkaran keramik lantai 10. Bongkar keramik dinding Pembongkaran keramik dinding 11. Bongkar bak mandi Pembongkaran bak mandi 12. Bongkar kloset jongkok Pembongkaran kloset jongkok 13. Bongkar fitting Pembongkaran fitting 14. Bongkar lampu Pembongkaran lampu 15. Bongkar pintu existing Pembongkaran pintu existing 16. Bongkar pintu KM/WC Pembongkaran pintu KM/WC C PEKERJAAN ATAP DAN PLAFOND 1. Pasang rangka atap baja ringan galvanize Mutu bagus kualitas baik standar pabrik baja ringan Galvanize G 550 Mpa AZ 220, tebal reng/batten 0, 5 mm, profil C 76.75 dan C76.100. 2. Pasang genteng morando glazur Mutu bagus kualitas baik standar pabrik Genteng morando glazur 3. Pasang karpusan genteng morando glazur Mutu bagus kualitas baik standar pabrik Karpusan genteng morando glazur 4. Pasang listplank GRC 30/30 Mutu bagus kualitas baik standar pabrik Bahan GRC t= 6 mm ukuran (3x20) cm, halus, diberi profil untuk lisplank dan dicat kayu. 5. Pasang rangka plafond Rangka hollow tebal hollow= 0.35 mm dengan kombinasi 20x40 dan 40x40 lengkap dengan drop celling atau upcelling jika ada 6. Pasang plafond PVC Bahan plafond PVC mutu bagus kualitas baik pemasangan rapi, jika ada sambungan tidak terlihat 7. Pasang lis plafond PVC Bahan lis dari bahan PVC ukuran 4atau 6 cm mutu bagus pemasangan rapi 8. Pasang rangka dan atap spandek Mutu bagus kualitas baik standar pabrik spandek ukuran 0,5 mm D PEKERJAAN PASANGAN 1. Pasang keramik lantai 30/30 Mutu bagus kualitas baik pekerjaan rapi keramic tile 30x30 setara Platinum 2. Pasang keramik dinding 30/60 Mutu bagus kualitas baik pekerjaan rapi keramic tile 30x60 setara platinum 3. Pasang keramik lantai 60/60 Mutu bagus kualitas baik pekerjaan rapi Granit tile 60x60 setara 4. Pasang bata sopi-sopi 1 : 5 Bata disusun dengan rapi mortar perbandingan 1 bagian portland cement (Pc) dan 5 bagian pasir pasang (Ps); tebal jadi ± 11 cm. 5. Plester 1 : 5 Bersihkan permukaan dinding dari kotoran, debu, dan material lepas lainnya; Pastikan permukaan dinding kering dan bebas dari kelembaban; Jika terdapat retakan atau lubang pada dinding, perbaiki terlebih dahulu dengan menggunakan mortar atau bahan perekat yang sesuai; Pasang waterpass atau garis lurus sebagai acuan untuk memastikan kesamaan ketinggian dan kerataan plestera; Siapkan alat dan bahan yang dibutuhkan, seperti semen, pasir, air, ember, cangkul, cetok, dan alat pengaduk. E PERBAIKAN KUSEN DAN PINTU 1. Pasang kusen pintu alumunium Mutu bagus kualitas baik bahan aluminium warna natural 4" x 1 ¾" tebal 0.75 mm setara Alexindo, kaca es tebal 5 mm, kanan dan kiri kaca mati, tengah hidup 2. Pasang daun pintu kayu lapis HPL Mutu bagus kualitas baik daun triplek pintu lapis HPL dengan rangka kayu 3. Pasang kusen jendela alumunium Mutu bagus kualitas baik bahan aluminium warna natural 4" x 1 ¾" tebal 0.75 mm setara Alexindo, kaca es tebal 5 mm, kanan dan kiri kaca mati, tengah hidup 4. Pasang daun jendela cashment Mutu bagus kualitas baik pekerjaan rapi 4" ex.ALEXINDO + kaca asahi 5mm 5. Pasang kunci pintu Mutu bagus kualitas baik setara Solid 6. Pasang kunci pintu bulat Mutu bagus kualitas baik setara Solid F PEKERJAAN INSTALASI LISTRIK 1. Pasang fitting lampu Mutu bagus kualitas baik standar pabrik ex Broco 2. Pasang lampu SL Mutu bagus kualitas baik setara Philips 3. Pas. instalasi titik lampu NYM 2x1,5 mm2 Mutu bagus kualitas baik SPLN Kabel ex.Supreme 4. Instalasi Stop kontak Mutu bagus kualitas baik SPLN Kabel ex.Supreme 5. Pasang Saklar seri Mutu bagus kualitas baik SPLN Kabel setara Broco 6. Pasang saklar tunggal Mutu bagus kualitas baik SPLN Kabel setara Broco 7. Pasang stop kontak Mutu bagus kualitas baik SPLN Kabel setara Broco 8. Box MCB + Assesoris Mutu bagus kualitas baik SPLN Kabel MCB setara Merlin Gerin G PEKERJAAN INSTALASI AIR 1. Pasang kloset jongkok Mutu bagus kualitas baik standar pabrik closed jongkok merk setara Toto 2. Pasang floordrain Floor drain sederhana, lengkap mangkuk perangkap udara/serangga, bahan bukan logam (plastik, PVC, dll) merk setara toto 3. Pasang kran air Mutu bagus kualitas baik standar pabrik merk setara Toto 4. Pasang pintu KM/WC PVC Mutu bagus kualitas baik pekerjaan rapi PVC H PEKERJAAN PENGECATAN 1. Pengecatan dinding luar ( 2 lapis ) Tembok diplamir, dihaluskan dengan amplas, dilapis cat dasar satu kali, dilapis cat penutup dua kali; cat tembok luar jenis weathershield dengan merk Jotun KW 1 type 6502 G, 3 lapis untuk kolom menggunakan warna darkgrey, untuk dinding menggunakan lightgrey Type 0967 2. Pengecatan dinding dalam ( 2 lapis ) Tembok diplamir, dihaluskan dengan amplas, dilapis cat dasar satu kali, dilapis cat penutup dua kali; cat tembok dalam dengan Vinilex 3 lapis 3. Waterproofing karpusan nok atap Plesteran dengan waterproofing coating tebal jadi ± 15 mm mutu bagus kualitas baik setara mowilex atau damdex 4. Pengecatan listplank Listplank diplamir, dihaluskan dengan amplas, dilapis cat dasar satu kali, dilapis cat penutup dua kali; cat besi/kayu setara Glotex I PEKERJAAN LAIN-LAIN 1. Pasang Torn air Mutu Bagus kualitas baik standar pabrik kapasitas 650 liter 2. Pemotongan pohon Pemotongan pohon dilaksanakan dengan rapi 3. Perbaikan saluran air keliling Perbaikan saluran air pembuangan saluran air kotor dengan pasangan bata finishing plesteran dan acian 4. Perbaikan dinding pagar pasangan bata Mutu bagus kualitas baik pekerjaan rapi finishing plesteran dan acian', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 138916);
