INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61987104', 61987104, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'LAPAS NARKOTIKA KELAS II A BANDAR LAMPUNG', 'Pengadaan Bahan Makanan Tahanan, Anak, Narapidana, Anak Binaan dan Anak Bawaan pada Lapas Narkotika Kelas IIA Bandar Lampung – Lampung Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Lampung, Bandar Lampung (Kota)', 6913100000, 'December 2025', 'APBN - RUPIAH MURNI PENDAMPING (C)', 1, 1, '1 Paket', 'Pengadaan 23 item bahan makanan sesuai permen imipas 1 tahun 2025', '1. Beras berkualitas medium, bersih, tidak apek, tidak banyak gabah, tidak terdapat kerikil, tidak terdapat kutu beras. 2. Ubi/ Ketela Segar dan bersih. 3. Daging sapi Segar, sedikit urat/lemak, tidak berlendir, tidak mengandung bahan pengawet, kondisi daging tidak bolehlebih lama dari satu hari sesudah pemotongan. 4. Ayam Ras/ Boiler Bersih, segar, muda, berat minimum 1 kg/ekor, tanpa isi, tidak suntik air, kulit belum keras (halal). 5. Telur Ayam Ras Kulit bersih, tidak busuk, tidak retak, dalam 1 kg berisi + 16 butir. 6. Kelapa Daging Segar, muda, terkupas, tidak tengik dan basi, putih, baru. 7. Sayur Segar: a. Harus yang sehat, bermutu baik dan segar serta mengandung zat makanan seperti kobis, sawi, wortel, labu terong, daun melinjo, kacang panjang, kangkung, ketimun dan lain-lain. b. Harus berganti-ganti setiap hari dan merupakan campuran sayuran yang beratnya berimbang. c. Tidak termasuk bagian sayur-sayuran yang tidak dapat dimakan. 8. Buah-buahan Tua, masak, dan tidak busuk. 9. Gula Pasir Kering, bersih, murni, dalam negeri/lokal, tidak hancur, tidak menggumpal, tidak mangkak 10. Bumbu segar Harus terdiri dari bermacam-macam rempah seperti : bawang merah, bawang putih, ketumbar, merica, kemiri, jintan, kunyit, jahe, salam, lengkuas, termasuk terasi, cabe, dan bumbu penyedap lainnya sesuai dengan jenis makanan yang tercantum dalam daftar menu. 11. Racikan Sambel Terdiri dari berbagai macam bumbubumbu dan rempah-rempah, disesuaikan dengan jenis makanan yang tercantum dalam daftar menu. 12. Garam Dapur Kering, bersih, beryodium, tidak expire, dengan merk dan nomor register beryodium. 13. Tahu Warna putih/kuning, segar, bersih, murni, padat, tidak hancur, mutu baik, tidak bergaram, tanpa formalin, kenyal, berat minimal 50 gram. 14. Tempe kedelai berkualitas baik, segar dan tidak busuk. 15. Kacang-kacangan Kering, bersih tua, terkupas, tidak hancur, tidak berjamur, tidak tengik, tidak berakar. 16. Kacang hijau Kering, bersih, tua, tidak berkutu. 17. Ikan Segar, berkilat, kenyal, tidak hancur, utuh, tidak berformalin. 18. Ikan Kering Bisa berupa ikan kering asin atau ikan kering tawar dengan spesifikasi kering dan bersih. 19. Minyak goreng Tidak tengik, dalam kemasan, 17 kg/dirigen, asli disegel, tidak isi ulang, tidak kadaluarsa, bersih, murni, tidak dicampur. 20. Gula Kelapa/ aren Kering, kuning, tidak bersampah, kualitas super, tidak keropos tanpa campur an. 21. Kecap Mutu nomor 1, manis, isi 620 ml/sct, kualitas baik, tidak expire, dalam kemasan bersegel, murni. 22. Gas yang murni dan jika diper gunakan untuk masak tidak memedihkan mata. 23. Air Minum Bersih, tidak, berbau, tidak berasa, tidak berwarna, dan tidak mengandung logam berat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 139971);
